CREATE TABLE public.design_catalogs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workflow_kind text NOT NULL CHECK(workflow_kind IN ('photo','marketing_design','order_mockup')), kind text NOT NULL CHECK(kind IN ('work','product')), name text NOT NULL CHECK(length(trim(name)) BETWEEN 1 AND 120), active boolean NOT NULL DEFAULT true, position integer NOT NULL DEFAULT 0, is_other boolean NOT NULL DEFAULT false, UNIQUE(workflow_kind,kind,name), CHECK(kind='work' OR workflow_kind='order_mockup'));
GRANT SELECT ON public.design_catalogs TO authenticated; GRANT ALL ON public.design_catalogs TO service_role;
ALTER TABLE public.design_catalogs ENABLE ROW LEVEL SECURITY;
CREATE POLICY design_catalog_read ON public.design_catalogs FOR SELECT TO authenticated USING(private.is_active(auth.uid()));
CREATE FUNCTION public.design_catalog_save(_id uuid,_flow text,_kind text,_name text,_active boolean,_position integer) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,private AS $$DECLARE result uuid; BEGIN IF NOT private.is_active(auth.uid()) OR NOT (private.is_admin(auth.uid()) OR private.has_permission(auth.uid(),'settings.role')) THEN RAISE EXCEPTION 'Không có quyền Cài đặt' USING ERRCODE='42501'; END IF; IF _id IS NULL THEN INSERT INTO design_catalogs(workflow_kind,kind,name,active,position) VALUES(_flow,_kind,trim(_name),_active,_position) RETURNING id INTO result; ELSE UPDATE design_catalogs SET name=trim(_name),active=_active,position=_position WHERE id=_id AND workflow_kind=_flow AND kind=_kind RETURNING id INTO result; IF result IS NULL THEN RAISE EXCEPTION 'Danh mục không tồn tại'; END IF; END IF; RETURN result; END $$;
REVOKE ALL ON FUNCTION public.design_catalog_save(uuid,text,text,text,boolean,integer) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.design_catalog_save(uuid,text,text,text,boolean,integer) TO authenticated;
CREATE FUNCTION public.design_catalog_usage() RETURNS TABLE(catalog_id uuid,orders_count bigint) LANGUAGE sql STABLE SECURITY INVOKER SET search_path=public AS $$ SELECT c.id,count(DISTINCT o.id) FROM design_catalogs c LEFT JOIN orders o ON o.data->>'workCategoryId'=c.id::text OR coalesce(o.data->'productIds','[]'::jsonb) ? c.id::text GROUP BY c.id $$;
REVOKE ALL ON FUNCTION public.design_catalog_usage() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.design_catalog_usage() TO authenticated;
CREATE FUNCTION public.design_input_access(_name text,_write boolean DEFAULT false) RETURNS boolean LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public,private AS $$ DECLARE r orders; parts text[]:=string_to_array(_name,'/'); BEGIN IF auth.uid() IS NULL OR NOT private.is_active(auth.uid()) OR array_length(parts,1)<>4 THEN RETURN false; END IF; SELECT * INTO r FROM orders WHERE id=parts[2]; IF FOUND THEN RETURN private.design_read(auth.uid(),r.created_by,r.data,r.workflow_kind) AND (NOT _write OR ((private.is_admin(auth.uid()) OR r.created_by=auth.uid() OR private.design_person(auth.uid(),r.data->>'assignee') OR public.design_can(auth.uid(),r.workflow_kind,'assign')) AND public.design_can(auth.uid(),r.workflow_kind,'edit'))); END IF; RETURN parts[1]=auth.uid()::text AND parts[3] IN ('photo','marketing_design','order_mockup') AND public.design_can(auth.uid(),parts[3],'create'); END $$;
REVOKE ALL ON FUNCTION public.design_input_access(text,boolean) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.design_input_access(text,boolean) TO authenticated;
CREATE POLICY design_input_select ON storage.objects FOR SELECT TO authenticated USING(bucket_id='design-inputs' AND public.design_input_access(name,false));
CREATE POLICY design_input_insert ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='design-inputs' AND public.design_input_access(name,true) AND lower(name) ~ '\.(pdf|doc|docx|xls|xlsx|ppt|pptx|jpg|jpeg|png|webp|gif|heic|ai|psd|eps|svg|tif|tiff|zip|txt|csv)$');
CREATE FUNCTION private.design_form_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,private AS $$ DECLARE d jsonb:=NEW.data; c design_catalogs; p jsonb; a jsonb; f text:=coalesce(d->>'workflowKind',NEW.workflow_kind); changed boolean; BEGIN
IF TG_OP='INSERT' THEN changed:=true; ELSE changed:=d->'workCategoryId' IS DISTINCT FROM OLD.data->'workCategoryId' OR d->'productIds' IS DISTINCT FROM OLD.data->'productIds' OR d->'otherProducts' IS DISTINCT FROM OLD.data->'otherProducts' OR d->'workOther' IS DISTINCT FROM OLD.data->'workOther' OR f IS DISTINCT FROM OLD.workflow_kind; END IF;
IF changed AND d->>'workCategoryId' IS NOT NULL THEN SELECT * INTO c FROM design_catalogs WHERE id=(d->>'workCategoryId')::uuid AND kind='work' AND workflow_kind=f; IF NOT FOUND THEN RAISE EXCEPTION 'Loại công việc không phù hợp với luồng'; END IF; IF NOT c.active AND (TG_OP='INSERT' OR d->>'workCategoryId' IS DISTINCT FROM OLD.data->>'workCategoryId') THEN RAISE EXCEPTION 'Danh mục đã ngừng sử dụng'; END IF; END IF;
IF changed AND d ? 'productIds' THEN IF jsonb_typeof(d->'productIds')<>'array' OR jsonb_array_length(d->'productIds')>30 OR (f<>'order_mockup' AND jsonb_array_length(d->'productIds')>0) THEN RAISE EXCEPTION 'Sản phẩm áp dụng không hợp lệ'; END IF;
FOR p IN SELECT value FROM jsonb_array_elements(d->'productIds') LOOP SELECT * INTO c FROM design_catalogs WHERE id=(p#>>'{}')::uuid AND kind='product' AND workflow_kind=f; IF NOT FOUND THEN RAISE EXCEPTION 'Sản phẩm không hợp lệ'; END IF; IF NOT c.active AND (TG_OP='INSERT' OR NOT coalesce(OLD.data->'productIds','[]') ? c.id::text) THEN RAISE EXCEPTION 'Sản phẩm đã ngừng sử dụng'; END IF; IF c.is_other THEN IF jsonb_typeof(d->'otherProducts') IS DISTINCT FROM 'array' OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements_text(d->'otherProducts') n WHERE length(trim(n)) BETWEEN 1 AND 120) OR EXISTS(SELECT 1 FROM jsonb_array_elements_text(d->'otherProducts') n WHERE length(trim(n)) NOT BETWEEN 1 AND 120) THEN RAISE EXCEPTION 'Nhập ít nhất một tên sản phẩm khác hợp lệ'; END IF; END IF; END LOOP;
IF NOT EXISTS(SELECT 1 FROM design_catalogs WHERE is_other AND kind='product' AND coalesce(d->'productIds','[]') ? id::text) THEN d:=d||jsonb_build_object('otherProducts','[]'::jsonb); END IF; END IF;
IF TG_OP='INSERT' OR d->'inputAttachments' IS DISTINCT FROM OLD.data->'inputAttachments' THEN IF d ? 'inputAttachments' THEN IF jsonb_typeof(d->'inputAttachments')<>'array' OR jsonb_array_length(d->'inputAttachments')>30 THEN RAISE EXCEPTION 'Tối đa 30 tài liệu'; END IF; FOR a IN SELECT value FROM jsonb_array_elements(d->'inputAttachments') LOOP IF a->>'kind'='link' THEN IF coalesce(a->>'url','') !~ '^https?://[^ /]+' OR length(a->>'url')>2048 THEN RAISE EXCEPTION 'Link không hợp lệ'; END IF; ELSIF a->>'kind'='file' THEN IF split_part(a->>'path','/',2)<>NEW.id OR NOT EXISTS(SELECT 1 FROM storage.objects WHERE bucket_id='design-inputs' AND name=a->>'path' AND public.design_input_access(name,false)) THEN RAISE EXCEPTION 'Tệp chưa tải thành công hoặc không có quyền'; END IF; ELSE RAISE EXCEPTION 'Tài liệu không hợp lệ'; END IF; END LOOP; END IF; END IF;
NEW.data:=d; RETURN NEW; END $$;
CREATE TRIGGER design_order_z_form_guard BEFORE INSERT OR UPDATE ON public.orders FOR EACH ROW EXECUTE FUNCTION private.design_form_guard();